function Room({ name, service, percent }: { name: string; service: string; percent: number }) { return <div><div className="mb-2 flex items-end justify-between"><div><p className="text-sm font-semibold">{name}</p><p className="text-[11px] text-[#7b8d89]">{service}</p></div><span className="text-xs font-semibold text-[#138675]">{percent}%</span></div><div className="h-1.5 overflow-hidden rounded-full bg-[#e8f0ee]"><div className="h-full rounded-full bg-[#37a995]" style={{ width: `${percent}%` }} /></div></div>; }
