function ProfessionalsSection(){
 const [query,setQuery]=useState(""); const visible=professionals.filter(p=>p.name.toLowerCase().includes(query.toLowerCase())||p.role.toLowerCase().includes(query.toLowerCase()));
 return <div className="space-y-5"><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><PatientStat label="Profissionais ativos" value="12" note="Equipe multidisciplinar" icon={UsersRound}/><PatientStat label="Atendendo agora" value="4" note="Em 4 salas diferentes" icon={Activity}/><PatientStat label="Agenda hoje" value="18" note="14 confirmados" icon={CalendarClock}/><PatientStat label="Acessos ativos" value="11" note="1 convite pendente" icon={ShieldCheck}/></section>
 <div className="flex flex-wrap items-center gap-3 rounded-2xl border border-[#dce7e4] bg-white p-4"><div className="relative min-w-[230px] flex-1"><Search className="absolute left-3 top-2.5 size-4 text-[#899b96]"/><Input value={query} onChange={e=>setQuery(e.target.value)} className="pl-9" placeholder="Buscar profissional ou especialidade..."/></div><Select defaultValue="todos"><SelectTrigger className="w-[180px]"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="todos">Todas as áreas</SelectItem><SelectItem value="medicina">Medicina</SelectItem><SelectItem value="fisioterapia">Fisioterapia</SelectItem><SelectItem value="psicologia">Psicologia</SelectItem></SelectContent></Select><Dialog><DialogTrigger asChild><Button className="bg-[#138675] hover:bg-[#0f6d60]"><Plus/> Novo profissional</Button></DialogTrigger><DialogContent className="sm:max-w-[560px]"><DialogHeader><DialogTitle>Cadastrar profissional</DialogTitle><DialogDescription>Defina os dados, agenda, acesso e regra de repasse.</DialogDescription></DialogHeader><div className="grid gap-4"><div className="grid grid-cols-2 gap-3"><FormBox title="Nome completo"><Input placeholder="Nome do profissional"/></FormBox><FormBox title="Especialidade"><Input placeholder="Ex.: Fisioterapia"/></FormBox></div><div className="grid grid-cols-2 gap-3"><FormBox title="Conselho"><Input placeholder="CREFITO, CRM, CRP..."/></FormBox><FormBox title="Número"><Input placeholder="Registro profissional"/></FormBox></div><div className="grid grid-cols-2 gap-3"><FormBox title="Início do expediente"><Input type="time"/></FormBox><FormBox title="Fim do expediente"><Input type="time"/></FormBox></div><FormBox title="Modalidades atendidas"><Input placeholder="Consulta, retorno, fisioterapia..."/></FormBox><FormBox title="Regra de repasse"><Input placeholder="Ex.: 45% por atendimento"/></FormBox><Button className="bg-[#138675] hover:bg-[#0f6d60]">Salvar profissional</Button></div></DialogContent></Dialog></div>
 <section className="grid gap-4 lg:grid-cols-2">{visible.map(p=><ProfessionalCard key={p.name} p={p}/>)}</section>
 <section className="rounded-2xl border border-[#dce7e4] bg-white"><div className="flex items-center border-b border-[#e3ebe9] p-5"><div><h3 className="font-semibold">Disponibilidade semanal</h3><p className="text-xs text-[#788a85]">Visão resumida da equipe</p></div><Button variant="outline" className="ml-auto"><CalendarDays size={15}/> Configurar horários</Button></div><div className="overflow-x-auto"><div className="min-w-[800px]"><div className="grid grid-cols-[200px_repeat(6,1fr)] bg-[#fafcfb] text-center text-[10px] font-bold text-[#778a85]"><span className="p-3 text-left">PROFISSIONAL</span>{["SEG","TER","QUA","QUI","SEX","SÁB"].map(d=><span key={d} className="border-l border-[#e4ecea] p-3">{d}</span>)}</div>{professionals.map((p,i)=><div key={p.name} className="grid grid-cols-[200px_repeat(6,1fr)] border-t border-[#e9efed]"><div className="p-3"><p className="text-xs font-semibold">{p.name}</p><p className="text-[10px] text-[#82938f]">{p.hours}</p></div>{[0,1,2,3,4,5].map(d=><div key={d} className="grid place-items-center border-l border-[#e9efed] p-2"><div className={`h-7 w-full rounded-lg ${(d+i)%2===0||i===2?"bg-[#cceae3]":"bg-[#f3f7f6]"}`}/></div>)}</div>)}</div></div><div className="flex gap-5 border-t border-[#e4ecea] p-4"><Legend color="bg-[#89cdbc]" label="Disponível"/><Legend color="bg-[#eef4f2]" label="Sem expediente"/></div></section></div>;
}
function ProfessionalCard({p}:{p:typeof professionals[number]}){return <Sheet><SheetTrigger asChild><button className="rounded-2xl border border-[#dce7e4] bg-white p-5 text-left transition hover:-translate-y-0.5 hover:shadow-lg hover:shadow-[#244f46]/5"><div className="flex items-start"><div className={`grid size-12 place-items-center rounded-2xl font-bold ${p.color}`}>{p.initials}</div><div className="ml-3"><h3 className="text-sm font-semibold">{p.name}</h3><p className="text-[11px] text-[#6f837d]">{p.role}</p><p className="mt-1 text-[10px] text-[#899995]">{p.council}</p></div><Badge className={`ml-auto text-[10px] ${p.status==="Disponível"?"bg-emerald-100 text-emerald-700":"bg-blue-100 text-blue-700"}`}>{p.status}</Badge></div><div className="my-4 flex flex-wrap gap-1.5">{p.modes.map(m=><Badge key={m} variant="outline" className="text-[10px]">{m}</Badge>)}</div><div className="grid grid-cols-3 gap-2"><MiniMetric label="HOJE" value={p.today}/><MiniMetric label="HORÁRIO" value={p.hours}/><MiniMetric label="REPASSE" value={p.repasse}/></div></button></SheetTrigger><ProfessionalSheet p={p}/></Sheet>}
function MiniMetric({label,value}:{label:string;value:string}){return <div className="rounded-xl bg-[#f6f9f8] p-3"><p className="text-[9px] font-bold text-[#879793]">{label}</p><p className="mt-1 truncate text-[11px] font-semibold">{value}</p></div>}
function ProfessionalSheet({p}:{p:typeof professionals[number]}){return <SheetContent className="w-full overflow-y-auto sm:max-w-[560px]"><SheetHeader><div className="flex items-center gap-4"><div className={`grid size-14 place-items-center rounded-2xl font-bold ${p.color}`}>{p.initials}</div><div><SheetTitle>{p.name}</SheetTitle><SheetDescription>{p.role} · {p.council}</SheetDescription></div></div></SheetHeader><Tabs defaultValue="agenda" className="mt-6"><TabsList className="grid w-full grid-cols-3"><TabsTrigger value="agenda">Agenda</TabsTrigger><TabsTrigger value="acesso">Permissões</TabsTrigger><TabsTrigger value="repasse">Repasse</TabsTrigger></TabsList><TabsContent value="agenda" className="mt-5 space-y-4"><DetailCard title="Disponibilidade"><Detail icon={CalendarDays} text={p.week}/><Detail icon={Clock3} text={p.hours}/></DetailCard><DetailCard title="Atendimentos de hoje">{["08:00 · Marina Carvalho","10:30 · Helena Costa","14:00 · Pedro Matos"].map(x=><p key={x} className="border-b border-[#e8efed] py-3 text-xs last:border-0">{x}</p>)}</DetailCard></TabsContent><TabsContent value="acesso" className="mt-5"><DetailCard title="Permissões do sistema"><Permission label="Visualizar própria agenda" checked/><Permission label="Criar agendamentos" checked/><Permission label="Acessar prontuários atribuídos" checked/><Permission label="Visualizar financeiro geral"/><Permission label="Editar usuários e permissões"/></DetailCard></TabsContent><TabsContent value="repasse" className="mt-5"><DetailCard title="Regra atual"><p className="text-2xl font-semibold text-[#138675]">{p.repasse}</p><p className="mt-1 text-xs text-[#768984]">Sobre atendimentos realizados e recebidos</p><div className="mt-4 rounded-xl bg-[#f5f9f8] p-4"><p className="text-xs text-[#758883]">Estimativa do mês</p><p className="mt-1 text-lg font-semibold">R$ 3.740,00</p></div></DetailCard></TabsContent></Tabs></SheetContent>}
function Permission({label,checked=false}:{label:string;checked?:boolean}){return <div className="flex items-center justify-between border-b border-[#e8efed] py-3 last:border-0"><span className="text-xs">{label}</span><Switch defaultChecked={checked}/></div>}

const settingNav=[["Dados da clínica",Building2],["Modalidades",Stethoscope],["Agenda e horários",CalendarClock],["Pacotes e pagamentos",WalletCards],["Usuários e acessos",UserCog],["Notificações",Bell],["Segurança e LGPD",ShieldCheck],["Aparência",Palette]] as const;
function SettingsSection(){const [section,setSection]=useState("Dados da clínica");const [saved,setSaved]=useState(false);const save=()=>{setSaved(true);setTimeout(()=>setSaved(false),2200)};return <div className="grid gap-5 xl:grid-cols-[260px_1fr]"><aside className="h-fit rounded-2xl border border-[#dce7e4] bg-white p-2">{settingNav.map(([name,Icon])=><button key={name} onClick={()=>setSection(name)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-xs font-medium transition ${section===name?"bg-[#e5f4f0] text-[#087565]":"text-[#667b76] hover:bg-[#f4f8f7]"}`}><Icon size={17}/>{name}</button>)}</aside><section className="overflow-hidden rounded-2xl border border-[#dce7e4] bg-white"><div className="flex items-center border-b border-[#e4ecea] bg-[#fafcfb] p-5"><div><h2 className="font-semibold">{section}</h2><p className="text-xs text-[#788b86]">Configurações gerais da demonstração</p></div><Button onClick={save} className="ml-auto bg-[#138675] hover:bg-[#0f6d60]"><Save size={15}/> Salvar alterações</Button></div><div className="p-5 md:p-6"><SettingsContent section={section}/></div></section>{saved&&<div className="fixed bottom-5 right-5 z-50 rounded-xl bg-[#173e37] px-5 py-3 text-sm font-medium text-white shadow-xl">Configurações demonstrativas salvas.</div>}</div>}
function SettingsContent({section}:{section:string}){
 if(section==="Dados da clínica")return <div className="space-y-6"><div className="flex items-center gap-4 rounded-2xl bg-[#f5faf8] p-4"><div className="grid size-16 place-items-center rounded-2xl bg-[#138675] text-white"><Activity size={28}/></div><div><p className="text-sm font-semibold">Identidade da clínica</p><p className="text-xs text-[#71847f]">Logo, nome e dados institucionais</p><Button variant="outline" size="sm" className="mt-2 bg-white">Alterar logotipo</Button></div></div><div className="grid gap-4 md:grid-cols-2"><FormBox title="Nome da clínica"><Input defaultValue="Clínica Recriar"/></FormBox><FormBox title="CNPJ"><Input placeholder="00.000.000/0000-00"/></FormBox><FormBox title="Telefone"><Input defaultValue="(24) 2017-3540"/></FormBox><FormBox title="E-mail"><Input defaultValue="contato@clinicarecriar.com.br"/></FormBox></div><FormBox title="Endereço"><Input defaultValue="Estrada União e Indústria, Nogueira — Petrópolis/RJ"/></FormBox></div>;
 if(section==="Modalidades")return <SettingList rows={[["Fisioterapia","50 minutos · R$ 120,00"],["Clínica médica","50 minutos · R$ 180,00"],["Psicologia","50 minutos · R$ 140,00"],["Pilates","50 minutos · até 6 pessoas"],["Terapia integrada","50 minutos · R$ 130,00"]]} button="Nova modalidade"/>;
 if(section==="Agenda e horários")return <div className="space-y-5"><DetailCard title="Funcionamento geral">{[["Segunda a sexta","07:00 às 20:00"],["Sábado","08:00 às 14:00"],["Domingo","Fechado"]].map(r=><div key={r[0]} className="grid grid-cols-2 border-b border-[#e8efed] py-3 text-xs last:border-0"><strong>{r[0]}</strong><span>{r[1]}</span></div>)}</DetailCard><DetailCard title="Regras da agenda"><Permission label="Bloquear conflito de profissional" checked/><Permission label="Bloquear conflito de sala" checked/><Permission label="Permitir encaixes pela recepção" checked/><Permission label="Permitir agendamento retroativo"/><Permission label="Exigir confirmação do paciente" checked/></DetailCard></div>;
 if(section==="Pacotes e pagamentos")return <div className="space-y-5"><SettingList rows={[["Fisioterapia · 10 sessões","R$ 850,00 · validade de 90 dias"],["Psicologia · 8 sessões","R$ 960,00 · validade de 60 dias"],["Pilates · 12 sessões","R$ 620,00 · validade de 45 dias"]]} button="Novo pacote"/><DetailCard title="Formas aceitas"><Permission label="Pix" checked/><Permission label="Cartão de crédito" checked/><Permission label="Cartão de débito" checked/><Permission label="Dinheiro" checked/><Permission label="Boleto"/></DetailCard></div>;
 if(section==="Usuários e acessos")return <SettingList rows={[["Edmilson","Administrador · acesso completo"],["Recepção","Agenda, pacientes e pagamentos"],["Dra. Ana Martins","Agenda e prontuários atribuídos"],["Camila Rocha","Agenda e prontuários atribuídos"]]} button="Convidar usuário"/>;
 if(section==="Notificações")return <DetailCard title="Avisos automáticos"><Permission label="Lembrete de consulta ao paciente" checked/><Permission label="Aviso de pacote terminando" checked/><Permission label="Alerta de pagamento pendente" checked/><Permission label="Aviso de alteração na agenda" checked/><Permission label="Resumo financeiro diário"/></DetailCard>;
 if(section==="Segurança e LGPD")return <div className="space-y-5"><div className="flex gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4 text-xs leading-5 text-amber-900"><ShieldCheck className="shrink-0" size={19}/><p>Antes do uso real, será necessário revisar bases legais, política de privacidade, retenção, backups e resposta a incidentes.</p></div><DetailCard title="Proteções"><Permission label="Login individual obrigatório" checked/><Permission label="Registrar acessos a prontuários" checked/><Permission label="Histórico de alterações clínicas" checked/><Permission label="Encerrar sessões inativas" checked/><Permission label="Autenticação em duas etapas"/></DetailCard><DetailCard title="Dados e continuidade"><SettingLine icon={Database} title="Backup automático" note="Configurar antes do uso real"/><SettingLine icon={FileText} title="Política de privacidade" note="Documento pendente de revisão"/><SettingLine icon={Download} title="Exportação de dados do paciente" note="Prevista para a versão operacional"/></DetailCard></div>;
 return <div className="space-y-5"><DetailCard title="Tema do sistema"><div className="grid grid-cols-3 gap-3">{["Verde Recriar","Azul sereno","Neutro"].map((x,i)=><button key={x} className={`rounded-xl border p-4 text-xs font-semibold ${i===0?"border-[#138675] bg-[#edf8f5]":"border-[#dfe8e6]"}`}><i className={`mx-auto mb-3 block size-8 rounded-full ${i===0?"bg-[#138675]":i===1?"bg-blue-500":"bg-slate-500"}`}/>{x}</button>)}</div></DetailCard><DetailCard title="Exibição"><Permission label="Menu lateral compacto"/><Permission label="Mostrar valores no painel inicial" checked/><Permission label="Usar animações suaves" checked/></DetailCard></div>;
}
function SettingList({rows,button}:{rows:string[][];button:string}){return <div><div className="space-y-2">{rows.map(r=><div key={r[0]} className="flex items-center gap-3 rounded-xl border border-[#e0e9e7] p-4"><div className="grid size-9 place-items-center rounded-lg bg-[#e8f5f1] text-[#138675]"><SlidersHorizontal size={16}/></div><div><p className="text-xs font-semibold">{r[0]}</p><p className="text-[11px] text-[#788b86]">{r[1]}</p></div><Button variant="ghost" size="icon" className="ml-auto"><MoreHorizontal size={17}/></Button></div>)}</div><Button variant="outline" className="mt-4"><Plus size={15}/>{button}</Button></div>}
function SettingLine({icon:Icon,title,note}:{icon:typeof Database;title:string;note:string}){return <div className="flex items-center gap-3 border-b border-[#e8efed] py-3 last:border-0"><Icon size={17} className="text-[#138675]"/><div><p className="text-xs font-semibold">{title}</p><p className="text-[10px] text-[#80918d]">{note}</p></div><ChevronRight className="ml-auto text-[#91a09c]" size={16}/></div>}
